class PremiumMainActivity : ComponentActivity() {
    lateinit var db: Db
    private var voiceResult: ((String) -> Unit)? = null
    private val voiceLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { r ->
        if (r.resultCode == Activity.RESULT_OK) {
            val text = r.data?.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS)?.firstOrNull().orEmpty()
            if (text.isNotBlank()) voiceResult?.invoke(text.trim())
        }
    }
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState); db = Db(this); askNotifications()
        setContent { PremiumTheme { PlannerApp(this, db) } }
    }
    fun voice(cb: (String) -> Unit) {
        voiceResult = cb
        val i = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, "tr-TR")
        }
        try { voiceLauncher.launch(i) } catch (_: ActivityNotFoundException) {}
    }
    fun pickDate(d: LocalDate, cb: (LocalDate) -> Unit) = DatePickerDialog(this,{_,y,m,dd->cb(LocalDate.of(y,m+1,dd))},d.year,d.monthValue-1,d.dayOfMonth).show()
    fun pickTime(t: LocalTime, cb: (LocalTime) -> Unit) = TimePickerDialog(this,{_,h,m->cb(LocalTime.of(h,m))},t.hour,t.minute,true).show()
    private fun askNotifications(){ if(Build.VERSION.SDK_INT>=33 && checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED) requestPermissions(arrayOf(Manifest.permission.POST_NOTIFICATIONS),901) }
}

