    primary=Color(0xFF4B57E8), onPrimary=Color.White, primaryContainer=Color(0xFFE8EAFF),
    secondary=Color(0xFF7259D8), secondaryContainer=Color(0xFFEEE9FF),
    background=Color(0xFFF7F8FC), surface=Color.White, surfaceVariant=Color(0xFFF0F2F8),
    onSurface=Color(0xFF191B24), onSurfaceVariant=Color(0xFF697080), outline=Color(0xFFD9DDE8)
)
private val Dark = darkColorScheme(
    primary=Color(0xFFBBC2FF), onPrimary=Color(0xFF1C276E), primaryContainer=Color(0xFF303B8B),
    secondary=Color(0xFFD1C7FF), secondaryContainer=Color(0xFF493C8A),
    background=Color(0xFF0F1116), surface=Color(0xFF17191F), surfaceVariant=Color(0xFF232630),
    onSurface=Color(0xFFF4F4F7), onSurfaceVariant=Color(0xFFB5B9C5), outline=Color(0xFF3C404B)
)
@Composable fun PremiumTheme(c:@Composable()->Unit){ MaterialTheme(colorScheme=if(androidx.compose.foundation.isSystemInDarkTheme()) Dark else Light, shapes=Shapes(small=RoundedCornerShape(12.dp),medium=RoundedCornerShape(20.dp),large=RoundedCornerShape(28.dp)),content=c) }

enum class PScreen{TODAY,HISTORY,TOPICS,SEARCH,TOPIC}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun PlannerApp(a:PremiumMainActivity, db:Db){
    var screen by rememberSaveable{ mutableStateOf(PScreen.TODAY) }
    var dateText by rememberSaveable{ mutableStateOf(LocalDate.now().toString()) }
    var topicId by rememberSaveable{ mutableStateOf(0L) }
    var query by rememberSaveable{ mutableStateOf("") }
    var rev by remember{ mutableIntStateOf(0) }
    var add by remember{ mutableStateOf(false) }; var taskEdit by remember{ mutableStateOf<Db.Item?>(null) }; var noteEdit by remember{ mutableStateOf<Db.Item?>(null) }
    var showTask by remember{ mutableStateOf(false) }; var showNote by remember{ mutableStateOf(false) }; var showQuick by remember{ mutableStateOf(false) }; var chosen by remember{ mutableStateOf<Db.Item?>(null) }
    val d=runCatching{LocalDate.parse(dateText)}.getOrDefault(LocalDate.now())
    val dayItems=remember(screen,dateText,rev){ if(screen==PScreen.TODAY) db.getItemsForDay(dateText) else emptyList() }
    val stats=remember(screen,dateText,rev){ db.getDayStats(dateText) }
    val events=remember(screen,dateText,rev){ if(screen==PScreen.HISTORY) db.getEventsForDay(dateText) else emptyList() }
    val topics=remember(screen,rev){ if(screen==PScreen.TOPICS||screen==PScreen.TOPIC) db.getTopics() else emptyList() }
    val topicItems=remember(screen,topicId,rev){ if(screen==PScreen.TOPIC) db.getItemsForTopic(topicId) else emptyList() }
    val results=remember(screen,query,rev){ if(screen==PScreen.SEARCH&&query.isNotBlank()) db.searchItems(query) else emptyList() }
    fun refresh(){rev++}

    Scaffold(
        containerColor=MaterialTheme.colorScheme.background,
        topBar={ PremiumTop(screen,d,if(screen==PScreen.TOPIC)db.getTopic(topicId) else null){screen=PScreen.TOPICS} },
        bottomBar={ NavigationBar(containerColor=MaterialTheme.colorScheme.surface){
            nav(Icons.Rounded.Home,"Bugün",screen==PScreen.TODAY){screen=PScreen.TODAY;dateText=LocalDate.now().toString()}
            nav(Icons.Rounded.CalendarMonth,"Geçmiş",screen==PScreen.HISTORY){screen=PScreen.HISTORY}
            nav(Icons.Rounded.Folder,"Konular",screen==PScreen.TOPICS||screen==PScreen.TOPIC){screen=PScreen.TOPICS}
            nav(Icons.Rounded.Search,"Ara",screen==PScreen.SEARCH){screen=PScreen.SEARCH}
        }},
        floatingActionButton={ ExtendedFloatingActionButton(onClick={add=true},icon={Icon(Icons.Rounded.Add,null)},text={Text("Ekle",fontWeight=FontWeight.SemiBold)}) }
    ){pad->
        when(screen){
            PScreen.TODAY->TodayPage(d,stats,dayItems,{dateText=it.toString()},{a.pickDate(d){dateText=it.toString()}},{chosen=it},{item->
                if(item.status==Db.STATUS_DONE)db.reopenItem(item.id) else { val n=db.completeItem(item.id); ReminderScheduler.cancel(a,item.id); if(n>0) db.getItem(n)?.let{if(it.dueAt>System.currentTimeMillis())ReminderScheduler.schedule(a,it.id,it.dueAt)} };refresh()
            },{ a.voice{text-> val p=NaturalLanguageParser.parse(text,d); val t=TopicEngine.findMatchingTopic(db,p.title,p.original); val id=db.insertItem(Db.TYPE_TASK,p.title,"",p.dayKey,p.dueAt,t,p.recurrence,p.durationMinutes,p.priority);if(p.dueAt>0)ReminderScheduler.schedule(a,id,p.dueAt);dateText=p.dayKey;refresh()} },{
                val plan=SmartPlanner.propose(db.getOpenTasksUpTo(LocalDate.now().toString()),LocalDate.now()); plan.forEach{ReminderScheduler.cancel(a,it.itemId);db.rescheduleItem(it.itemId,it.newDayKey,it.newDueAt);ReminderScheduler.schedule(a,it.itemId,it.newDueAt)};dateText=LocalDate.now().toString();refresh()
            },Modifier.padding(pad))
            PScreen.HISTORY->HistoryPage(d,stats,events,{dateText=it.toString()},{a.pickDate(d){dateText=it.toString()}},Modifier.padding(pad))
            PScreen.TOPICS->TopicsPage(topics,db,{topicId=it;screen=PScreen.TOPIC},Modifier.padding(pad))
            PScreen.TOPIC->TopicPage(db.getTopic(topicId),topicItems,{chosen=it},Modifier.padding(pad))
            PScreen.SEARCH->SearchPage(query,{query=it},results,{chosen=it},Modifier.padding(pad))
        }
    }

    if(add) AddSheet({add=false},{add=false;showQuick=true},{add=false;taskEdit=null;showTask=true},{add=false;noteEdit=null;showNote=true},{add=false;a.voice{text->val p=NaturalLanguageParser.parse(text,d);val t=TopicEngine.findMatchingTopic(db,p.title,p.original);val id=db.insertItem(Db.TYPE_TASK,p.title,"",p.dayKey,p.dueAt,t,p.recurrence,p.durationMinutes,p.priority);if(p.dueAt>0)ReminderScheduler.schedule(a,id,p.dueAt);dateText=p.dayKey;refresh()}},{add=false;a.voice{text->val title=TopicEngine.suggestTitle(text);val t=if(screen==PScreen.TOPIC)topicId else TopicEngine.findOrCreateTopic(db,title,text);db.insertItem(Db.TYPE_NOTE,title,text,LocalDate.now().toString(),0,t);TopicEngine.refreshAutoTitle(db,t);refresh()}})
    if(showQuick) QuickDialog(d,{showQuick=false}){p->val t=TopicEngine.findMatchingTopic(db,p.title,p.original);val id=db.insertItem(Db.TYPE_TASK,p.title,"",p.dayKey,p.dueAt,t,p.recurrence,p.durationMinutes,p.priority);if(p.dueAt>0)ReminderScheduler.schedule(a,id,p.dueAt);dateText=p.dayKey;showQuick=false;refresh()}
    if(showTask) TaskDialog(taskEdit,d,a,{showTask=false}){title,body,day,time,dur,rec,pri->val due=if(time==null)0L else LocalDateTime.of(day,time).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();val old=taskEdit;if(old==null){val t=TopicEngine.findMatchingTopic(db,title,body);val id=db.insertItem(Db.TYPE_TASK,title,body,day.toString(),due,t,rec,dur,pri);if(due>0)ReminderScheduler.schedule(a,id,due)}else{ReminderScheduler.cancel(a,old.id);db.updateItem(old.id,title,body,day.toString(),due,old.topicId,rec,dur,pri);if(due>0&&old.status==Db.STATUS_OPEN)ReminderScheduler.schedule(a,old.id,due)};dateText=day.toString();showTask=false;refresh()}
    if(showNote) NoteDialog(noteEdit,{showNote=false}){title0,body->val title=title0.ifBlank{TopicEngine.suggestTitle(body)};val old=noteEdit;if(old==null){val t=if(screen==PScreen.TOPIC)topicId else TopicEngine.findOrCreateTopic(db,title,body);db.insertItem(Db.TYPE_NOTE,title,body,LocalDate.now().toString(),0,t);TopicEngine.refreshAutoTitle(db,t)}else{db.updateItem(old.id,title,body,old.dayKey,0,old.topicId,"",0,2)};showNote=false;refresh()}
    chosen?.let{item->ItemSheet(item,{chosen=null},{if(item.status==Db.STATUS_DONE)db.reopenItem(item.id) else db.completeItem(item.id);ReminderScheduler.cancel(a,item.id);chosen=null;refresh()},{val nd=LocalDate.parse(item.dayKey).plusDays(1);val due=if(item.dueAt>0){val t=Instant.ofEpochMilli(item.dueAt).atZone(ZoneId.systemDefault()).toLocalTime();LocalDateTime.of(nd,t).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()}else 0;db.postponeItem(item.id,nd.toString(),due);if(due>0)ReminderScheduler.schedule(a,item.id,due);chosen=null;refresh()},{chosen=null;if(item.type==Db.TYPE_NOTE){noteEdit=item;showNote=true}else{taskEdit=item;showTask=true}},{ReminderScheduler.cancel(a,item.id);db.deleteItem(item.id);chosen=null;refresh()})}
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun PremiumTop(s:PScreen,d:LocalDate,t:Db.Topic?,back:()->Unit){ val title=when(s){PScreen.TODAY->if(d==LocalDate.now())"Bugün" else d.format(DateTimeFormatter.ofPattern("d MMMM",Locale("tr","TR")));PScreen.HISTORY->"Geçmiş";PScreen.TOPICS->"Konular";PScreen.SEARCH->"Arama";PScreen.TOPIC->t?.title?:"Konu"}; CenterAlignedTopAppBar(title={Column(horizontalAlignment=Alignment.CenterHorizontally){Text(title,fontWeight=FontWeight.SemiBold,maxLines=1,overflow=TextOverflow.Ellipsis);if(s==PScreen.TODAY)Text(d.dayOfWeek.getDisplayName(TextStyle.FULL,Locale("tr","TR")),style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}},navigationIcon={if(s==PScreen.TOPIC)IconButton(onClick=back){Icon(Icons.Rounded.ArrowBack,null)}}) }
@Composable fun RowScope.nav(i:ImageVector,l:String,sel:Boolean,on:()->Unit){NavigationBarItem(sel,on,{Icon(i,l)},label={Text(l)},colors=NavigationBarItemDefaults.colors(indicatorColor=MaterialTheme.colorScheme.primaryContainer,selectedIconColor=MaterialTheme.colorScheme.primary))}

@Composable fun TodayPage(d:LocalDate,st:Db.DayStats,data:List<Db.Item>,date:(LocalDate)->Unit,pick:()->Unit,open:(Db.Item)->Unit,toggle:(Db.Item)->Unit,voice:()->Unit,plan:()->Unit,m:Modifier){val tasks=data.filter{it.type==Db.TYPE_TASK};val notes=data.filter{it.type==Db.TYPE_NOTE};val active=tasks.filter{it.status==Db.STATUS_OPEN};val next=active.filter{it.dueAt>0}.minByOrNull{it.dueAt}?:active.firstOrNull();val total=st.open+st.done;val pr=if(total==0)0f else st.done.toFloat()/total;LazyColumn(m.fillMaxSize(),contentPadding=PaddingValues(18.dp,8.dp,18.dp,116.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{DateStrip(d,date,pick)};item{Hero(st,pr)};if(next!=null)item{FocusCard(next,open)};item{LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){item{AssistChip(onClick=voice,label={Text("Sesle ekle")},leadingIcon={Icon(Icons.Rounded.KeyboardVoice,null,Modifier.size(18.dp))},colors=AssistChipDefaults.assistChipColors(containerColor=MaterialTheme.colorScheme.surface))};item{AssistChip(onClick=plan,label={Text("Akıllı plan")},leadingIcon={Icon(Icons.Rounded.AutoAwesome,null,Modifier.size(18.dp))},colors=AssistChipDefaults.assistChipColors(containerColor=MaterialTheme.colorScheme.surface))}}};item{Section("Bugünün planı",if(tasks.isEmpty())"Boş" else "${tasks.size} görev")};if(tasks.isEmpty())item{Empty("Günün boş görünüyor","İlk görevini ekle. Gün ilerledikçe gerektiği kadar eklemek daha gerçekçi bir plan sağlar.")}else items(tasks,key={it.id}){TaskCard(it,open,toggle)};if(notes.isNotEmpty()){item{Section("Notlar","${notes.size} kayıt")};items(notes,key={it.id}){NoteCard(it,open)}}}}
@Composable fun DateStrip(d:LocalDate,change:(LocalDate)->Unit,pick:()->Unit){val start=d.minusDays(3);Row(verticalAlignment=Alignment.CenterVertically){LazyRow(Modifier.weight(1f),horizontalArrangement=Arrangement.spacedBy(8.dp)){items((0..6).map{start.plusDays(it.toLong())}){x->val a=x==d;Surface(onClick={change(x)},shape=RoundedCornerShape(18.dp),color=if(a)MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surface,contentColor=if(a)MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurface,modifier=Modifier.width(58.dp)){Column(Modifier.padding(vertical=10.dp),horizontalAlignment=Alignment.CenterHorizontally){Text(x.dayOfWeek.getDisplayName(TextStyle.SHORT,Locale("tr","TR")).uppercase(Locale("tr","TR")),style=MaterialTheme.typography.labelSmall);Text("${x.dayOfMonth}",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold)}}}};Spacer(Modifier.width(8.dp));IconButton(pick,Modifier.background(MaterialTheme.colorScheme.surface,CircleShape)){Icon(Icons.Rounded.CalendarMonth,null)}}}
@Composable fun Hero(s:Db.DayStats,p:Float){Card(shape=RoundedCornerShape(28.dp),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surface)){Column(Modifier.padding(20.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("Günün dengesi",color=MaterialTheme.colorScheme.primary,fontWeight=FontWeight.SemiBold);Text(if(s.open==0&&s.done>0)"Plan tamamlandı" else if(s.open>=6)"Yoğun bir gün" else "Kontrol sende",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold)};Text("%${(p*100).toInt()}",style=MaterialTheme.typography.titleLarge,color=MaterialTheme.colorScheme.primary)};LinearProgressIndicator(progress={p},modifier=Modifier.fillMaxWidth().height(8.dp).clip(CircleShape));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){pill("${s.open} açık",MaterialTheme.colorScheme.primaryContainer,MaterialTheme.colorScheme.onPrimaryContainer);pill("${s.done} tamam",Color(0xFFE5F7ED),Color(0xFF176A44));pill("${s.notes} not",Color(0xFFFFF1D1),Color(0xFF8C5700))}}}}
