@Composable fun HistoryPage(d:LocalDate,s:Db.DayStats,e:List<Db.Event>,change:(LocalDate)->Unit,pick:()->Unit,m:Modifier){LazyColumn(m.fillMaxSize(),contentPadding=PaddingValues(18.dp,8.dp,18.dp,116.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{DateStrip(d,change,pick)};item{Hero(s,if(s.open+s.done==0)0f else s.done.toFloat()/(s.open+s.done))};item{Section("Hareket günlüğü","${e.size} kayıt")};if(e.isEmpty())item{Empty("Bu gün sakin geçmiş","Oluşturma, tamamlama veya erteleme hareketi görünmüyor.")}else items(e,key={it.id}){x->Row{Text(Instant.ofEpochMilli(x.createdAt).atZone(ZoneId.systemDefault()).toLocalTime().format(DateTimeFormatter.ofPattern("HH:mm")),Modifier.width(52.dp),color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.width(10.dp));Surface(shape=RoundedCornerShape(18.dp),color=MaterialTheme.colorScheme.surface,modifier=Modifier.weight(1f)){Column(Modifier.padding(14.dp)){Text(event(x.eventType),color=eventColor(x.eventType),fontWeight=FontWeight.Bold,style=MaterialTheme.typography.labelMedium);Text(x.titleSnapshot,fontWeight=FontWeight.SemiBold);if(x.details.isNotBlank())Text(x.details,color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.bodySmall)}}}}}}
@Composable fun TopicsPage(t:List<Db.Topic>,db:Db,open:(Long)->Unit,m:Modifier){LazyColumn(m.fillMaxSize(),contentPadding=PaddingValues(18.dp,8.dp,18.dp,116.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Surface(shape=RoundedCornerShape(26.dp),color=MaterialTheme.colorScheme.secondaryContainer){Column(Modifier.padding(20.dp)){Text("Konu hafızası",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Farklı günlerde aldığın benzer notlar tek başlık altında toplansın.",color=MaterialTheme.colorScheme.onSurfaceVariant)}}};item{Section("Konular","${t.size} başlık")};if(t.isEmpty())item{Empty("Henüz konu yok","İlk notundan sonra konu hafızası oluşmaya başlayacak.")}else items(t,key={it.id}){x->Card(onClick={open(x.id)},shape=RoundedCornerShape(22.dp),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surface)){Row(Modifier.padding(17.dp),verticalAlignment=Alignment.CenterVertically){Surface(shape=RoundedCornerShape(15.dp),color=MaterialTheme.colorScheme.secondaryContainer){Icon(Icons.Rounded.Folder,null,Modifier.padding(11.dp).size(22.dp),tint=MaterialTheme.colorScheme.secondary)};Spacer(Modifier.width(13.dp));Column(Modifier.weight(1f)){Text(x.title,fontWeight=FontWeight.SemiBold);Text("${db.countItemsInTopic(x.id)} kayıt • otomatik ${if(x.autoGroup)"açık" else "kapalı"}",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Icon(Icons.Rounded.ChevronRight,null)}}}}}
@Composable fun TopicPage(t:Db.Topic?,data:List<Db.Item>,open:(Db.Item)->Unit,m:Modifier){LazyColumn(m.fillMaxSize(),contentPadding=PaddingValues(18.dp,8.dp,18.dp,116.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Surface(shape=RoundedCornerShape(26.dp),color=MaterialTheme.colorScheme.secondaryContainer){Column(Modifier.padding(20.dp)){Text(t?.title?:"Konu",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Bu konunun kronolojik hafızası",color=MaterialTheme.colorScheme.onSurfaceVariant)}}};item{Section("Kayıtlar","${data.size}")};if(data.isEmpty())item{Empty("Bu konu boş","Yeni bir not veya görev ekleyebilirsin.")}else items(data,key={it.id}){if(it.type==Db.TYPE_NOTE)NoteCard(it,open)else Surface(onClick={open(it)},shape=RoundedCornerShape(20.dp),color=MaterialTheme.colorScheme.surface){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Icon(if(it.status==Db.STATUS_DONE)Icons.Rounded.CheckCircle else Icons.Rounded.RadioButtonUnchecked,null,tint=if(it.status==Db.STATUS_DONE)Color(0xFF24A66A)else MaterialTheme.colorScheme.primary);Spacer(Modifier.width(12.dp));Column{Text(it.title,fontWeight=FontWeight.SemiBold);Text(it.dayKey+(if(it.dueAt>0)" • ${time(it.dueAt)}" else ""),style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}}}}
@Composable fun SearchPage(q:String,set:(String)->Unit,r:List<Db.Item>,open:(Db.Item)->Unit,m:Modifier){LazyColumn(m.fillMaxSize(),contentPadding=PaddingValues(18.dp,8.dp,18.dp,116.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{OutlinedTextField(q,set,Modifier.fillMaxWidth(),singleLine=true,leadingIcon={Icon(Icons.Rounded.Search,null)},trailingIcon={if(q.isNotEmpty())IconButton({set("")}){Icon(Icons.Rounded.Close,null)}},placeholder={Text("Görev, not veya konu ara")},shape=RoundedCornerShape(22.dp))};item{Section(if(q.isBlank())"Hızlı bul" else "Sonuçlar",if(q.isBlank())"Geçmişin tamamı" else "${r.size} kayıt")};if(q.isBlank())item{Empty("Her şeyi bulabilirsin","Bir kelime yaz; görev ve not içeriklerinde de arama yapılır.")}else if(r.isEmpty())item{Empty("Sonuç yok","Daha genel bir kelimeyle tekrar dene.")}else items(r,key={it.id}){if(it.type==Db.TYPE_NOTE)NoteCard(it,open)else Surface(onClick={open(it)},shape=RoundedCornerShape(20.dp),color=MaterialTheme.colorScheme.surface){Row(Modifier.padding(16.dp)){Icon(if(it.status==Db.STATUS_DONE)Icons.Rounded.CheckCircle else Icons.Rounded.RadioButtonUnchecked,null);Spacer(Modifier.width(12.dp));Column{Text(it.title,fontWeight=FontWeight.SemiBold);Text(it.dayKey,color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.bodySmall)}}}}}}

