@Composable fun AddSheet(close:()->Unit,quick:()->Unit,task:()->Unit,note:()->Unit,voiceTask:()->Unit,voiceNote:()->Unit){ModalBottomSheet(onDismissRequest=close){Column(Modifier.fillMaxWidth().padding(horizontal=20.dp).padding(bottom=28.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Hızlı ekle",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Aklındakini en az dokunuşla kaydet.",color=MaterialTheme.colorScheme.onSurfaceVariant);option(Icons.Rounded.AutoAwesome,"Akıllı görev","Doğal dille tarih, saat ve süre yaz",quick);option(Icons.Rounded.Today,"Ayrıntılı görev","Tarih, saat, süre, tekrar ve öncelik",task);option(Icons.Rounded.Notes,"Not","Bilgi, fikir veya kayıt",note);option(Icons.Rounded.KeyboardVoice,"Sesle görev","Konuşarak görev oluştur",voiceTask);option(Icons.Rounded.Mic,"Sesli not","Konuş ve konu hafızasına kaydet",voiceNote)}}}
@Composable fun option(i:ImageVector,t:String,s:String,on:()->Unit){Surface(onClick=on,shape=RoundedCornerShape(20.dp),color=MaterialTheme.colorScheme.surfaceVariant.copy(alpha=.7f)){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Surface(shape=RoundedCornerShape(14.dp),color=MaterialTheme.colorScheme.primaryContainer){Icon(i,null,Modifier.padding(10.dp).size(22.dp),tint=MaterialTheme.colorScheme.primary)};Spacer(Modifier.width(14.dp));Column{Text(t,fontWeight=FontWeight.SemiBold);Text(s,style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}}
@Composable fun QuickDialog(d:LocalDate,close:()->Unit,save:(NaturalLanguageParser.ParsedTask)->Unit){var txt by remember{mutableStateOf("")};val p=remember(txt){if(txt.isBlank())null else NaturalLanguageParser.parse(txt,d)};AlertDialog(close,title={Text("Akıllı görev")},text={Column(verticalArrangement=Arrangement.spacedBy(12.dp)){OutlinedTextField(txt,{txt=it},Modifier.fillMaxWidth(),label={Text("Doğal dille yaz")},placeholder={Text("Yarın 14:30 Ahmet'i ara 30 dk")},minLines=3,shape=RoundedCornerShape(18.dp));if(p!=null)Surface(shape=RoundedCornerShape(18.dp),color=MaterialTheme.colorScheme.primaryContainer){Column(Modifier.padding(14.dp)){Text(p.title,fontWeight=FontWeight.SemiBold);Text(p.dayKey+(if(p.dueAt>0)" • ${time(p.dueAt)}" else ""))}}}},confirmButton={Button({p?.let(save)},enabled=p!=null){Text("Ekle")}},dismissButton={TextButton(close){Text("Vazgeç")}})}
@Composable fun TaskDialog(i:Db.Item?,base:LocalDate,a:PremiumMainActivity,close:()->Unit,save:(String,String,LocalDate,LocalTime?,Int,String,Int)->Unit){var title by remember{mutableStateOf(i?.title.orEmpty())};var body by remember{mutableStateOf(i?.body.orEmpty())};var day by remember{mutableStateOf(i?.dayKey?.let{runCatching{LocalDate.parse(it)}.getOrNull()}?:base)};var tm by remember{mutableStateOf(i?.dueAt?.takeIf{it>0}?.let{Instant.ofEpochMilli(it).atZone(ZoneId.systemDefault()).toLocalTime()})};var dur by remember{mutableIntStateOf(i?.durationMinutes?:30)};var rec by remember{mutableStateOf(i?.recurrence.orEmpty())};var pri by remember{mutableIntStateOf(i?.priority?:2)};AlertDialog(close,title={Text(if(i==null)"Yeni görev" else "Görevi düzenle")},text={LazyColumn(Modifier.height(500.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{OutlinedTextField(title,{title=it},Modifier.fillMaxWidth(),label={Text("Görev")},shape=RoundedCornerShape(18.dp))};item{OutlinedTextField(body,{body=it},Modifier.fillMaxWidth(),label={Text("Açıklama")},minLines=2,shape=RoundedCornerShape(18.dp))};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton({a.pickDate(day){day=it}},Modifier.weight(1f)){Text(day.format(DateTimeFormatter.ofPattern("d MMM",Locale("tr","TR"))))};OutlinedButton({a.pickTime(tm?:LocalTime.of(9,0)){tm=it}},Modifier.weight(1f)){Text(tm?.format(DateTimeFormatter.ofPattern("HH:mm"))?:"Saat")}}};item{Text("Süre",fontWeight=FontWeight.SemiBold);LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){items(listOf(15,30,45,60,90)){x->FilterChip(dur==x,{dur=x},{Text("$x dk")})}}};item{Text("Öncelik",fontWeight=FontWeight.SemiBold);LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){items(listOf(0 to "Acil",1 to "Önemli",2 to "Normal")){(x,l)->FilterChip(pri==x,{pri=x},{Text(l)})}}};item{Text("Tekrar",fontWeight=FontWeight.SemiBold);LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){items(listOf("" to "Yok",NaturalLanguageParser.DAILY to "Her gün",NaturalLanguageParser.WEEKDAYS to "Hafta içi",NaturalLanguageParser.WEEKLY to "Her hafta",NaturalLanguageParser.MONTHLY to "Her ay")){(x,l)->FilterChip(rec==x,{rec=x},{Text(l)})}}}}},confirmButton={Button({save(title.trim(),body.trim(),day,tm,dur,rec,pri)},enabled=title.isNotBlank()){Text("Kaydet")}},dismissButton={TextButton(close){Text("Vazgeç")}})}
@Composable fun NoteDialog(i:Db.Item?,close:()->Unit,save:(String,String)->Unit){var t by remember{mutableStateOf(i?.title.orEmpty())};var b by remember{mutableStateOf(i?.body.orEmpty())};AlertDialog(close,title={Text(if(i==null)"Yeni not" else "Notu düzenle")},text={Column(verticalArrangement=Arrangement.spacedBy(12.dp)){OutlinedTextField(t,{t=it},Modifier.fillMaxWidth(),label={Text("Başlık")},shape=RoundedCornerShape(18.dp));OutlinedTextField(b,{b=it},Modifier.fillMaxWidth(),label={Text("Not")},minLines=6,shape=RoundedCornerShape(18.dp))}},confirmButton={Button({save(t.trim(),b.trim())},enabled=t.isNotBlank()||b.isNotBlank()){Text("Kaydet")}},dismissButton={TextButton(close){Text("Vazgeç")}})}
@OptIn(ExperimentalMaterial3Api::class)
@Composable fun ItemSheet(i:Db.Item,close:()->Unit,complete:()->Unit,tomorrow:()->Unit,edit:()->Unit,delete:()->Unit){ModalBottomSheet(onDismissRequest=close){Column(Modifier.fillMaxWidth().padding(horizontal=22.dp).padding(bottom=30.dp)){Text(i.title,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text(i.dayKey+(if(i.dueAt>0)" • ${time(i.dueAt)}" else ""),color=MaterialTheme.colorScheme.onSurfaceVariant);if(i.body.isNotBlank()){Spacer(Modifier.height(16.dp));Text(i.body)};Spacer(Modifier.height(20.dp));if(i.type==Db.TYPE_TASK){Button(complete,Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp)){Icon(Icons.Rounded.Check,null);Spacer(Modifier.width(8.dp));Text(if(i.status==Db.STATUS_DONE)"Tekrar aç" else "Tamamla")};Spacer(Modifier.height(8.dp));OutlinedButton(tomorrow,Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp)){Text("Yarına ertele")}};Spacer(Modifier.height(8.dp));OutlinedButton(edit,Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp)){Icon(Icons.Rounded.Edit,null);Spacer(Modifier.width(8.dp));Text("Düzenle")};TextButton(delete,Modifier.fillMaxWidth(),colors=ButtonDefaults.textButtonColors(contentColor=MaterialTheme.colorScheme.error)){Icon(Icons.Rounded.Delete,null);Spacer(Modifier.width(8.dp));Text("Sil")}}}}

fun time(ms:Long)=Instant.ofEpochMilli(ms).atZone(ZoneId.systemDefault()).toLocalTime().format(DateTimeFormatter.ofPattern("HH:mm"))
fun priority(p:Int)=when(p){0->Color(0xFFE04B4B);1->Color(0xFFF59E0B);else->Color(0xFF5969E8)}
fun event(t:String)=when(t){"CREATED"->"Oluşturuldu";"NOTE_CREATED"->"Not alındı";"COMPLETED"->"Tamamlandı";"POSTPONED"->"Ertelendi";"MOVED_IN"->"Taşındı";"EDITED"->"Düzenlendi";"DELETED"->"Silindi";"REOPENED"->"Tekrar açıldı";"RECUR_CREATED"->"Tekrar oluşturuldu";"SCHEDULED"->"Planlandı";else->t}
fun eventColor(t:String)=when(t){"COMPLETED"->Color(0xFF24A66A);"POSTPONED","DELETED"->Color(0xFFE04B4B);"NOTE_CREATED"->Color(0xFFF59E0B);else->Color(0xFF5969E8)}
